// GENERATED BLOCK — do not hand-edit. Move power/energy/duration, converted
// DIRECTLY from Niantic's raw GAME_MASTER (via PokeMiners' community mirror)
// by scripts/import_move_data.py — specifically each move's Gym & Raid
// `moveSettings` template, NOT PvPoke's gamemaster.json. PvPoke is a PvP
// battle simulator, so its move list is built from `combatMove` (Trainer
// Battle) stat overrides; this app never simulates PvP battles (PvP ranking
// here is CP/stat-product only), so every damage number it shows (Attackers
// board, Raid Counters, move detail) is a Gym & Raid context, and the old
// PvP-sourced table was quietly wrong for a lot of moves — e.g. Mud Shot is
// power 4/energy 6 in Gym & Raid vs power 3/energy 9 in Trainer Battles.
// Same authority tier as BASE_STATS above — replaces the old per-user,
// AI-guessed moveDB as the primary source; that AI lookup now only runs as
// a fallback for anything genuinely missing here. A handful of moves with
// conflicting Gym & Raid stats under the same display name would be excluded
// rather than guessed at (see import_move_data.py) — none exist as of this
// snapshot; genuinely form-dependent moves (Morpeko's Aura Wheel) are kept
// as separate per-form entries instead.
// Real per-species Mega Evolution energy costs, sourced from Niantic's raw
// GAME_MASTER via scripts/import_mega_data.py (same source/authority tier as
// AUTHORITATIVE_MOVES below). `first` is the one-time cost to Mega Evolve a
// species for the first time; `subsequent` is the reduced cost every time
// after that (species-level, matches how megaEnergyInventory already tracks
// energy — not per-individual Pokemon). Species with two forms (Charizard,
// Mewtwo, Raichu) list both MEGA_X and MEGA_Y separately. Primal Reversion
// (Groudon, Kyogre) is deliberately excluded — it's a different mechanic
// with its own resource, not Mega Energy, despite a similarly-shaped cost
// field in the raw data.
// Real per-species evolution data (next stage, candy cost, required item),
